use grep_matcher::Matcher;

use crate::{
    line_buffer::{LineBufferReader, DEFAULT_BUFFER_CAPACITY},
    lines::{self, LineStep},
    searcher::{core::Core, Config, Range, Searcher},
    sink::{Sink, SinkError},
};

#[derive(Debug)]
pub(crate) struct ReadByLine<'s, M, R, S> {
    config: &'s Config,
    core: Core<'s, M, S>,
    rdr: LineBufferReader<'s, R>,
}

